from __future__ import annotations
import html
from pathlib import Path
from typing import Any

def esc(value:Any)->str: return html.escape(str(value if value is not None else ""))
def _status(value):
    text=str(value).upper()
    if text in {"PASS","DONE","READY","COMPLETE","ACCEPTED","SATURATED","DIAGNOSTIC_SATURATED","PASS_CANDIDATE","AVAILABLE"} or value is True: return "ok"
    if text in {"FAIL","GAPS_OPEN","BLOCKER","REGENERATE_REQUIRED","INVALID"} or value is False: return "bad"
    return "wait"
def metric(label,value,hint=""): return f'<div class="metric {_status(value)}"><span>{esc(label)}</span><b>{esc(value)}</b>{f"<small>{esc(hint)}</small>" if hint else ""}</div>'
def table(items,cols,empty="Nessun elemento registrato"):
    if not items: return f'<p class="muted">{esc(empty)}</p>'
    head="".join(f"<th>{esc(label)}</th>" for label,_ in cols); rows=[]
    for item in items:
        cells=[]
        for _,accessor in cols:
            value=accessor(item) if callable(accessor) else item.get(accessor,"")
            if isinstance(value,(list,tuple,set)): value=", ".join(map(str,value))
            cells.append(f"<td>{esc(value)}</td>")
        rows.append("<tr>"+"".join(cells)+"</tr>")
    return f'<div class="table-wrap"><table><thead><tr>{head}</tr></thead><tbody>{"".join(rows)}</tbody></table></div>'
def _blockers(state):
    reason=(state.get("completion") or {}).get("reason","")
    return [] if not reason or reason=="PASS" else [x.strip() for x in str(reason).split(";") if x.strip()]
def _next_action(state):
    choices=((state.get("interaction") or {}).get("card") or {}).get("choices") or []
    return str(choices[0]) if choices else "Consulta i blocker e completa il passaggio successivo"
def render_session_dashboard(state:dict[str,Any],output:str|Path)->Path:
    req=state.get("request") or {}; mode=state.get("mode") or "NON SELEZIONATA"; completion=state.get("completion") or {}; ret=state.get("reticulum") or {}; mode_contract=state.get("mode_contract") or {}; editorial=state.get("editorial_standard") or {}; continuation=state.get("continuation") or {}; coverage=continuation.get("coverage") or {}; review=state.get("review") or {}; final_review=state.get("final_review") or {}; provenance=state.get("provenance") or {}; quality=state.get("quality") or {}; source_intel=state.get("source_intelligence") or {}; bibliography=state.get("bibliography") or {}; artifacts=state.get("artifacts") or []; claims=state.get("claim_ledger") or []; sources=state.get("sources") or []; cycles=review.get("cycles") or []; findings=cycles[-1].get("findings",[]) if cycles else []; blockers=_blockers(state); ready=bool(completion.get("eligible")); accepted=(state.get("setup") or {}).get("accepted") or {}; required_roles=mode_contract.get("required_artifact_roles") or []
    page=f'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Juriscribe — fascicolo di sessione</title><style>:root{{--bg:#f6f3ec;--paper:#fffdfa;--ink:#252825;--muted:#6b6f69;--line:#ddd6c8;--ok:#236443;--bad:#973d36;--wait:#92701c;--accent:#365f77}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 Georgia,'Times New Roman',serif}}main{{max-width:1180px;margin:auto;padding:22px}}header,section{{background:var(--paper);border:1px solid var(--line);border-radius:12px;margin:12px 0;padding:20px}}h1,h2,h3,.eyebrow,.metric,.next,th{{font-family:Arial,sans-serif}}h1{{margin:.2rem 0 .5rem;font-size:2rem}}h2{{font-size:1.25rem;margin-top:0}}.eyebrow{{font-size:.73rem;letter-spacing:.09em;text-transform:uppercase;color:var(--accent);font-weight:800}}.verdict{{font:800 1.55rem Arial,sans-serif;margin:.5rem 0}}.ok{{color:var(--ok)}}.bad{{color:var(--bad)}}.wait{{color:var(--wait)}}.next{{padding:12px 14px;background:#eef3f5;border-left:5px solid var(--accent);border-radius:7px}}.blockers{{padding:12px 16px;background:#fff0ee;border-left:5px solid var(--bad)}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:9px}}.metric{{padding:10px;border:1px solid var(--line);border-radius:8px;background:#fff}}.metric span{{display:block;font-size:.7rem;text-transform:uppercase;color:var(--muted)}}.metric b{{display:block;font-size:1.02rem}}.metric small{{display:block;color:var(--muted)}}.table-wrap{{overflow:auto}}table{{border-collapse:collapse;width:100%;font-size:.9rem}}th,td{{border-bottom:1px solid #ebe5d9;text-align:left;padding:8px;vertical-align:top}}th{{font-size:.72rem;text-transform:uppercase}}details{{margin:.65rem 0}}summary{{cursor:pointer;font-family:Arial,sans-serif;font-weight:700}}.muted{{color:var(--muted)}}code{{background:#f0ece3;padding:2px 5px;border-radius:4px}}@media(max-width:700px){{main{{padding:8px}}header,section{{padding:14px}}}}</style></head><body><main><header><div class="eyebrow">Juriscribe · fascicolo giuridico-scientifico-editoriale</div><h1>{esc(req.get('summary') or req.get('raw') or 'Sessione Juriscribe')}</h1><div class="verdict {'ok' if ready else 'bad'}">{'PRONTO PER CONSEGNA' if ready else 'NON PRONTO'}</div><p><strong>Modalità:</strong> <code>{esc(mode)}</code> · <strong>Tipo:</strong> {esc(editorial.get('document_type','non definito'))}</p><div class="next"><strong>Prossima azione:</strong> {esc(_next_action(state))}</div>{('<div class="blockers"><strong>Blocker</strong><ul>'+''.join(f'<li>{esc(x)}</li>' for x in blockers)+'</ul></div>') if blockers else '<p class="ok"><strong>Nessun blocker aperto.</strong></p>'}</header><section><h2>1. Stato e contratto di lavoro</h2><div class="grid">{metric('Modalità',mode)}{metric('Mode contract',mode_contract.get('status','NON PRONTO'))}{metric('Standard editoriale',editorial.get('status','NON PRONTO'),editorial.get('standard_id',''))}{metric('Reticolo',ret.get('status','NON ESEGUITO'))}{metric('Review',review.get('status','NON ESEGUITA'))}{metric('Qualità',quality.get('status','NON ESEGUITA'))}{metric('Provenance',provenance.get('status','NON ESEGUITA'))}{metric('Review finale',final_review.get('status','NON ESEGUITA'))}</div><h3>Parametri accettati</h3>{table([{'k':k,'v':v} for k,v in accepted.items()],[('Parametro','k'),('Valore','v')])}</section><section><h2>2. Standard redazionali applicati</h2><p><strong>{esc(editorial.get('standard_id',''))}</strong> · {esc(editorial.get('document_type',''))} · destinatari: {esc(editorial.get('audience',''))}</p>{table([{'regola':k,'valore':v} for k,v in (editorial.get('rules') or {}).items()],[('Regola','regola'),('Valore','valore')])}<p class="muted">Gli standard sono publisher-neutral: gerarchia, proporzione, terminologia, autorità, citazioni e leggibilità restano invarianti; sintassi citazionale e house style seguono il progetto.</p></section><section><h2>3. Evidenze e merito</h2><div class="grid">{metric('Claim',len(claims))}{metric('Fonti',len(sources))}{metric('Coverage fonti',source_intel.get('coverage_status','NON ESEGUITA'))}{metric('Bibliografia',bibliography.get('status','NON DISPONIBILE'))}{metric('Continuation',coverage.get('status',continuation.get('status','N/A')))}</div><details open><summary>Finding dell’ultima review ({len(findings)})</summary>{table(findings,[('Criterio','criterion'),('Gravità','severity'),('Problema',lambda x:x.get('message') or x.get('kind')),('Posizione','artifact_locator'),('Stato','status'),('Intervento','proposed_action')])}</details><details><summary>Fonti</summary>{table(sources,[('ID','id'),('Fonte','title'),('Ruolo','role'),('Lettura diretta','direct_read'),('Verifica','verified_at')])}</details></section><section><h2>4. Artefatti richiesti e prodotti</h2><p><strong>Ruoli richiesti per questa modalità:</strong> {esc(', '.join(required_roles))}</p>{table(artifacts,[('Ruolo','role'),('Artefatto','summary'),('Percorso','path'),('Readback','readback')])}</section><section><h2>5. Integrità tecnica</h2><details><summary>Mostra</summary><div class="grid">{metric('session.integrity.json',(state.get('node_integrity') or {}).get('status','NON VERIFICATO'))}{metric('Mode digest',mode_contract.get('digest',''))}{metric('Editorial digest',editorial.get('digest',''))}{metric('Provenance coverage',provenance.get('coverage','n/a'))}</div></details></section></main></body></html>'''
    out=Path(output); out.parent.mkdir(parents=True,exist_ok=True); out.write_text(page,encoding="utf-8"); return out
